        return singleton_stream(match_result)

def pattern_match(pattern, data, frame):
    if frame == 'failed':
        return 'failed'
    elif pattern == data:
        return frame
    elif is_variable(pattern):
        return extend_if_consistent(pattern, data, frame)
    elif is_pair(pattern) and is_pair(data):
        return pattern_match(tail(pattern), tail(data),
                             pattern_match(head(pattern), head(data), frame))
    else:
        return 'failed'

def extend_if_consistent(variable, data, frame):
