def apply_rules(pattern, frame):
    return stream_flatmap(
        lambda rule: apply_a_rule(rule, pattern, frame),
        fetch_rules(pattern, frame))

def apply_a_rule(rule, query_pattern, query_frame):
    clean_rule = rename_variables_in(rule)
    unify_result = unify_match(query_pattern, conclusion(clean_rule),
                               query_frame)
    if unify_result == 'failed':
        return None
    else:
        return evaluate_query(rule_body(clean_rule),
                              singleton_stream(unify_result))

def rename_variables_in(rule):
    rule_application_id = new_rule_application_id()
    def tree_walk(exp):
        if is_variable(exp):
            return make_new_variable(exp, rule_application_id)
        elif is_pair(exp):
            return pair(tree_walk(head(exp)), tree_walk(tail(exp)))
        else:
            return exp
    return tree_walk(rule)

def unify_match(p1, p2, frame):
    if frame == 'failed':
        return 'failed'
    elif p1 == p2:
        return frame
    elif is_variable(p1):
        return extend_if_possible(p1, p2, frame)
    elif is_variable(p2):
        return extend_if_possible(p2, p1, frame)
    elif is_pair(p1) and is_pair(p2):
        return unify_match(tail(p1), tail(p2),
                           unify_match(head(p1), head(p2), frame))
    else:
        return 'failed'

def extend_if_possible(variable, value, frame):
    binding = binding_in_frame(variable, frame)
    if not is_none(binding):
        return unify_match(binding_value(binding), value, frame)
    elif is_variable(value):
        binding = binding_in_frame(value, frame)
        if not is_none(binding):
            return unify_match(variable, binding_value(binding), frame)
        else:
            return extend(variable, value, frame)
    elif depends_on(value, variable, frame):
        return 'failed'
    else:
        return extend(variable, value, frame)

def depends_on(expression, variable, frame):
    def tree_walk(e):
        if is_variable(e):
            if variable == e:
                return True
            else:
                b = binding_in_frame(e, frame)
                if is_none(b):
                    return False
                else:
                    return tree_walk(binding_value(b))
        elif is_pair(e):
            return tree_walk(head(e)) or tree_walk(tail(e))
        else:
            return False
    return tree_walk(expression)

