def convert_to_query_syntax(exp):
    if is_application(exp):
        function_symbol = symbol_of_name(function_expression(exp))
        if function_symbol == 'python_predicate':
            return pair(function_symbol, arg_expressions(exp))
        else:
            processed_args = map(convert_to_query_syntax, arg_expressions(exp))
            if function_symbol == 'pair':
                return pair(head(processed_args), head(tail(processed_args)))
            elif function_symbol == 'llist':
                return processed_args
            else:
                return pair(function_symbol, processed_args)
    elif is_variable(exp):
        return exp
    else:
        return literal_value(exp)

def instantiate_expression(expression, frame):
    if is_variable(expression):
        return convert(instantiate_term(expression, frame))
    elif is_pair(expression):
        return pair(instantiate_expression(head(expression), frame),
                    instantiate_expression(tail(expression), frame))
    else:
        return expression

def instantiate_term(term, frame):
    if is_variable(term):
        binding = binding_in_frame(term, frame)
        if is_none(binding):
            return term
        else:
            return instantiate_term(binding_value(binding), frame)
    elif is_pair(term):
        return pair(instantiate_term(head(term), frame),
                    instantiate_term(tail(term), frame))
    else:
        return term

def convert(term):
    if is_variable(term):
        return term
    elif is_pair(term):
        return make_application(make_name('pair'),
                                llist(convert(head(term)),
                                      convert(tail(term))))
    else:
        return make_literal(term)

