def comma_separated(strings):
    def join(s, acc):
        if acc == '':
            return s
        else:
            return s + ', ' + acc
    return reduce(join, '', strings)

def is_llist_construction(exp):
    if is_literal(exp):
        return is_none(literal_value(exp))
    elif is_application(exp) and is_name(function_expression(exp)):
        return (symbol_of_name(function_expression(exp)) == 'pair' and
                is_llist_construction(head(tail(arg_expressions(exp)))))
    else:
        return False

